using CodeAssist.Core;using System;using System.IO;using Xunit;
public class ClipboardMenuSettingsTests {
[Theory][InlineData(true)][InlineData(false)]public void MenuChoiceSurvivesSaveAndDraftIsolation(bool enabled){var directory=Path.Combine(Path.GetTempPath(),"CA-Paste-"+Guid.NewGuid());var file=Path.Combine(directory,"settings.xml");try {var settings=new StartupPreferences {ClipboardMenuEnabled=enabled,ClipboardLimit=17};settings.Save(file);var loaded=StartupPreferences.Load(file);Assert.Equal(enabled,loaded.ClipboardMenuEnabled);Assert.Equal(17,loaded.ClipboardLimit);var draft=loaded.Copy();draft.ClipboardMenuEnabled=!enabled;Assert.Equal(enabled,loaded.ClipboardMenuEnabled);}finally{if(Directory.Exists(directory))Directory.Delete(directory,true);}}
[Fact]public void ExistingSettingsKeepMenuEnabled(){var directory=Path.Combine(Path.GetTempPath(),"CA-Paste-"+Guid.NewGuid());Directory.CreateDirectory(directory);var file=Path.Combine(directory,"settings.xml");try{File.WriteAllText(file,"<StartupPreferences><ClipboardLimit>12</ClipboardLimit></StartupPreferences>");var loaded=StartupPreferences.Load(file);Assert.True(loaded.ClipboardMenuEnabled);Assert.Equal(12,loaded.ClipboardLimit);}finally{Directory.Delete(directory,true);}}
}